29	function StarPicker({ value, onChange }: { value: number; onChange: (v: number) => void }) {
30	  const [hovered, setHovered] = useState(0);
31	  return (
32	    <div className="flex gap-2 justify-center">
33	      {[1, 2, 3, 4, 5].map((star) => (
34	        <button
35	          key={star}
36	          type="button"
37	          onMouseEnter={() => setHovered(star)}
38	          onMouseLeave={() => setHovered(0)}
39	          onClick={() => onChange(star)}
40	          className="focus:outline-none transition-transform hover:scale-110"
41	        >
42	          <Star
43	            className={`h-9 w-9 transition-colors ${
44	              star <= (hovered || value) ? "fill-yellow-400 text-yellow-400" : "text-muted-foreground/30"
45	            }`}
46	          />
47	        </button>
48	      ))}
49	    </div>
50	  );
51	}
