53	interface CoachReviewDialogProps {
54	  open: boolean;
55	  onClose: () => void;
56	  // existingReviewId !== undefined puts the dialog into edit mode: submits
57	  // a PATCH instead of POST, seeds the rating/comment from initialRating
58	  // and initialComment. Null means "no existing review yet".
59	  booking: {
60	    id: number;
61	    coachId: number;
62	    coachName: string;
63	    existingReviewId?: number | null;
64	    initialRating?: number;
65	    initialComment?: string | null;
66	  } | null;
