69	function CoachReviewDialog({ open, onClose, booking }: CoachReviewDialogProps) {
70	  const { toast } = useToast();
71	  const queryClient = useQueryClient();
72	  const [rating, setRating] = useState(0);
73	  const [comment, setComment] = useState("");
74	  const [submitting, setSubmitting] = useState(false);
75	  const isEdit = booking?.existingReviewId != null;
76	
77	  // Seed the form whenever the dialog opens. In edit mode we pull initial
78	  // values from the booking; in create mode we start clean. This effect runs
79	  // on every (open, booking.id) change so reopening with a different row
80	  // never leaks the previous one's values.
81	  useEffect(() => {
82	    if (open && booking) {
83	      setRating(booking.initialRating ?? 0);
84	      setComment(booking.initialComment ?? "");
85	    }
86	  }, [open, booking?.id, booking?.initialRating, booking?.initialComment, booking]);
87	
88	  const onSubmit = async () => {
89	    if (!booking || rating < 1 || submitting) return;
90	    setSubmitting(true);
91	    try {
92	      if (isEdit && booking.existingReviewId != null) {
93	        await customFetch(`${API_URL}/coach-reviews/${booking.existingReviewId}`, {
94	          method: "PATCH",
95	          headers: { "Content-Type": "application/json" },
96	          body: JSON.stringify({
97	            rating,
98	            comment: comment.trim() || null,
99	          }),
100	        });
101	        toast({ title: "Atsiliepimas atnaujintas" });
102	      } else {
103	        await customFetch(`${API_URL}/coach-reviews`, {
104	          method: "POST",
105	          headers: { "Content-Type": "application/json" },
106	          body: JSON.stringify({
107	            bookingId: booking.id,
108	            coachId: booking.coachId,
109	            rating,
110	            comment: comment.trim() || null,
111	          }),
112	        });
113	        toast({ title: "Atsiliepimas pateiktas", description: "Ačiū, kad pasidalinote patirtimi." });
114	      }
115	      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
116	      queryClient.invalidateQueries({ queryKey: ["coach-reviews", String(booking.coachId)] });
117	      queryClient.invalidateQueries({ queryKey: ["coach-reviews-me"] });
118	      queryClient.invalidateQueries({ queryKey: ["coaches"] });
119	      onClose();
120	    } catch (err) {
121	      const msg = (err as { data?: { error?: string }; message?: string })?.data?.error
122	        ?? (err as { message?: string })?.message
123	        ?? "Nepavyko išsaugoti atsiliepimo";
124	      toast({ title: "Klaida", description: msg, variant: "destructive" });
125	    } finally {
126	      setSubmitting(false);
127	    }
128	  };
129	
130	  return (
131	    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose(); }}>
132	      <DialogContent>
133	        <DialogHeader>
134	          <DialogTitle>{isEdit ? "Redaguoti atsiliepimą" : "Palikti atsiliepimą"}</DialogTitle>
135	          <DialogDescription>
136	            {booking ? `Įvertinkite trenerio ${booking.coachName} treniruotę.` : ""}
137	          </DialogDescription>
138	        </DialogHeader>
139	        <div className="space-y-4 py-2">
140	          <div className="space-y-2">
141	            <Label className="text-xs text-muted-foreground">Įvertinimas</Label>
142	            <StarPicker value={rating} onChange={setRating} />
143	          </div>
144	          <div className="space-y-2">
145	            <Label htmlFor="coach-review-comment" className="text-xs text-muted-foreground">
146	              Komentaras (neprivaloma)
147	            </Label>
148	            <Textarea
149	              id="coach-review-comment"
150	              rows={4}
151	              value={comment}
152	              onChange={(e) => setComment(e.target.value.slice(0, 2000))}
153	              placeholder="Kaip sekėsi treniruotė? Ką labiausiai įsiminėt?"
154	            />
155	          </div>
156	        </div>
157	        <DialogFooter>
158	          <Button variant="ghost" onClick={onClose} disabled={submitting}>
159	            Atšaukti
160	          </Button>
161	          <Button onClick={onSubmit} disabled={rating < 1 || submitting}>
162	            {submitting && <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />}
163	            {isEdit ? "Išsaugoti" : "Pateikti"}
164	          </Button>
165	        </DialogFooter>
166	      </DialogContent>
167	    </Dialog>
168	  );
169	}
