316	function CancelBookingDialog({
317	  bookingId,
318	  onClose,
319	  onConfirmed,
320	}: {
321	  bookingId: number | null;
322	  onClose: () => void;
323	  onConfirmed: (id: number) => Promise<void>;
324	}) {
325	  const t = useT();
326	  const open = bookingId !== null;
327	  const { data: preview, isLoading } = useGetRefundPreview(bookingId ?? 0, {
328	    query: { queryKey: getGetRefundPreviewQueryKey(bookingId ?? 0), enabled: open },
329	  });
330	  const [submitting, setSubmitting] = useState(false);
331	
332	  const hours = preview?.hoursBeforeStart ?? 0;
333	  const refundEur = preview?.refundAmount ?? 0;
334	  const isFreeSlot = (preview?.totalPrice ?? 0) <= 0;
335	  const isLate = !preview?.refundable;
336	  const tierKey = (preview?.refundPercent ?? 0) >= 80
337	    ? "bookings.cancel.tier80"
338	    : (preview?.refundPercent ?? 0) >= 50
339	      ? "bookings.cancel.tier50"
340	      : "bookings.cancel.tier0";
341	
342	  const handleConfirm = async () => {
343	    if (!bookingId) return;
344	    setSubmitting(true);
345	    try {
346	      await onConfirmed(bookingId);
347	      onClose();
348	    } finally {
349	      setSubmitting(false);
350	    }
351	  };
352	
353	  return (
354	    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
355	      <DialogContent className="max-w-md">
356	        <DialogHeader>
357	          <DialogTitle>{t("bookings.cancel.title")}</DialogTitle>
358	          <DialogDescription>
359	            {isLoading || !preview
360	              ? t("bookings.cancel.loading")
361	              : preview.canCancel
362	              ? isFreeSlot
363	                ? t("bookings.cancel.freeSlot").replace("{hours}", hours.toFixed(1))
364	                : t(tierKey)
365	              : preview.reason ?? t("bookings.cancel.notAllowed")}
366	          </DialogDescription>
367	        </DialogHeader>
368	
369	        {preview && preview.canCancel && !isFreeSlot && (
370	          <div className="rounded-lg border bg-muted/40 p-3 text-sm space-y-1.5">
371	            <div className="flex justify-between">
372	              <span className="text-muted-foreground">{t("bookings.cancel.totalPaid")}</span>
373	              <span className="font-medium">€{preview.totalPrice.toFixed(2)}</span>
374	            </div>
375	            <div className="flex justify-between">
376	              <span className="text-muted-foreground">{t("bookings.cancel.refundPercent")}</span>
377	              <span className="font-medium">{preview.refundPercent}%</span>
378	            </div>
379	            <div className="flex justify-between border-t pt-1.5 mt-1.5">
380	              <span className="font-semibold">{t("bookings.cancel.refundAmount")}</span>
381	              <span className={`font-bold ${isLate ? "text-destructive" : "text-green-600 dark:text-green-400"}`}>
382	                €{refundEur.toFixed(2)}
383	              </span>
384	            </div>
385	          </div>
386	        )}
387	
388	        <p className="text-xs text-muted-foreground">{t("bookings.cancel.policyShort")}</p>
389	
390	        <DialogFooter className="gap-2">
391	          <Button variant="outline" onClick={onClose} disabled={submitting}>
392	            {t("bookings.cancel.keep")}
393	          </Button>
394	          <Button
395	            variant="destructive"
396	            onClick={handleConfirm}
397	            disabled={submitting || !preview?.canCancel}
398	          >
399	            {submitting ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : null}
400	            {t("bookings.cancel.confirm")}
401	          </Button>
402	        </DialogFooter>
403	      </DialogContent>
404	    </Dialog>
405	  );
406	}
