408	function getStatusBadge(status: string, t: ReturnType<typeof useT>, refundAmount?: number, isSplit?: boolean) {
409	  switch (status) {
410	    case "confirmed":
411	      return <Badge className="bg-green-500 hover:bg-green-600 text-white text-xs"><CheckCircle2 className="w-3 h-3 mr-1" />{t("bookings.status.confirmed")}</Badge>;
412	    case "pending":
413	      if (isSplit) {
414	        return <Badge variant="secondary" className="bg-orange-500/20 text-orange-700 dark:text-orange-400 text-xs"><Clock className="w-3 h-3 mr-1" />Laukiama mokėjimo</Badge>;
415	      }
416	      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400 text-xs"><Clock className="w-3 h-3 mr-1" />{t("bookings.status.pending")}</Badge>;
417	    case "awaiting_players":
418	      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
419	    case "cancelled": {
420	      const r = Number(refundAmount ?? 0);
421	      const label = r > 0
422	        ? `${t("bookings.status.cancelled")} · ${t("bookings.cancel.refunded")} €${r.toFixed(2)}`
423	        : `${t("bookings.status.cancelled")} · ${t("bookings.cancel.noRefund")}`;
424	      return <Badge variant="destructive" className="text-xs"><XCircle className="w-3 h-3 mr-1" />{label}</Badge>;
425	    }
426	    default:
427	      return <Badge variant="outline" className="text-xs">{status}</Badge>;
428	  }
429	}
