431	function useCountdown(targetMs: number | null): string | null {
432	  const [label, setLabel] = useState<string | null>(null);
433	  useEffect(() => {
434	    if (targetMs === null) return;
435	    const update = () => {
436	      const diff = targetMs - Date.now();
437	      if (diff <= 0) { setLabel("Laikas baigėsi"); return; }
438	      const h = Math.floor(diff / 3600000);
439	      const m = Math.floor((diff % 3600000) / 60000);
440	      const s = Math.floor((diff % 60000) / 1000);
441	      if (h > 0) setLabel(`${h} val. ${m} min.`);
442	      else if (m > 0) setLabel(`${m} min. ${s} sek.`);
443	      else setLabel(`${s} sek.`);
444	    };
445	    update();
446	    const id = setInterval(update, 1000);
447	    return () => clearInterval(id);
448	  }, [targetMs]);
449	  return label;
450	}
