452	function BookingCard({
453	  booking,
454	  isUpcoming,
455	  onRate,
456	  onReviewCoach,
457	  onCancel,
458	  cancelling,
459	}: {
460	  booking: BookingItem;
461	  isUpcoming: boolean;
462	  onRate: () => void;
463	  onReviewCoach: () => void;
464	  onCancel: () => void;
465	  cancelling: boolean;
466	}) {
467	  const t = useT();
468	  const [, setLocation] = useLocation();
469	
470	  const dateLabel = format(booking.date, "yyyy-MM-dd");
471	  const dayLabel = format(booking.date, "EEEE", { locale: lt });
472	  const createdLabel = booking.createdAt
473	    ? format(new Date(booking.createdAt), "yyyy-MM-dd HH:mm")
474	    : null;
475	
476	  // Guarantee deadline = game start − 2 h (only relevant for awaiting_players split bookings)
477	  const guaranteeDeadlineMs = (booking.isSplit && booking.status === "awaiting_players")
478	    ? new Date(`${dateLabel}T${booking.startTime}:00`).getTime() - 2 * 60 * 60 * 1000
479	    : null;
480	  const countdown = useCountdown(guaranteeDeadlineMs);
481	
482	  // Defensive override: treat any unresolved booking (pending or awaiting_players)
483	  // whose game start has already passed as failed — covers both sweeper misses and
484	  // abandoned host checkouts (pending split with no confirmation).
485	  const gameStartMs = new Date(`${dateLabel}T${booking.startTime}:00`).getTime();
486	  const isZombieBooking = (booking.status === "awaiting_players" || booking.status === "pending")
487	    && Date.now() > gameStartMs;
488	
489	  return (
490	    <div
491	      className={`bg-card border rounded-xl p-4 space-y-3 cursor-pointer hover:border-primary/40 hover:shadow-sm transition-all group${isZombieBooking ? " opacity-60" : ""}`}
492	      onClick={() => setLocation(`/bookings/${booking.id}`)}
493	    >
494	      {/* Top row: headline + status. Coach lessons get a graduation icon and
495	          a "Pamoka su X" lead line, with the court name demoted to a small
496	          subline. Plain court rentals keep the original single-line layout. */}
497	      <div className="flex items-start justify-between gap-2">
498	        <div className="min-w-0 flex-1">
499	          {booking.coach ? (
500	            <>
501	              <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate flex items-center gap-1.5">
502	                <GraduationCap className="w-4 h-4 text-primary shrink-0" />
503	                Pamoka su {booking.coach.name}
504	              </p>
505	              <p className="text-xs text-muted-foreground mt-0.5 truncate">
506	                {booking.courtName || `Kortas #${booking.courtId}`}
507	              </p>
508	            </>
509	          ) : (
510	            <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate">
511	              {booking.courtName || `Kortas #${booking.courtId}`}
512	            </p>
513	          )}
514	        </div>
515	        <div className="flex items-center gap-1.5 shrink-0">
516	          {isZombieBooking
517	            ? <Badge variant="secondary" className="bg-red-500/20 text-red-700 dark:text-red-400 text-xs"><XCircle className="w-3 h-3 mr-1" />Nepavyko</Badge>
518	            : getStatusBadge(booking.status, t, booking.refundAmount, booking.isSplit)
519	          }
520	          <ChevronRight className="w-4 h-4 text-muted-foreground/50" />
521	        </div>
522	      </div>
523	
524	      {/* Date/time + price row */}
525	      <div className="flex items-center gap-4 text-sm text-muted-foreground">
526	        <span className="flex items-center gap-1.5">
527	          <Calendar className="w-3.5 h-3.5" />
528	          <span className="capitalize">{dayLabel},</span>
