101	// Booking `date`/`startTime` are stored as Lithuanian local time strings. The
102	// server runs in UTC, so naively parsing `${date}T${startTime}:00` would treat
103	// them as UTC and give a result that is wrong by Vilnius's DST offset (2–3h).
104	// Compute the UTC instant for the Vilnius wall-clock time, then diff against
105	// `Date.now()` in absolute milliseconds.
106	export function vilniusLocalToUtcMs(date: string, time: string): number {
107	  const dateOnly = String(date).slice(0, 10);
108	  // Step 1: pretend the local string is UTC.
109	  const naiveUtcMs = Date.parse(`${dateOnly}T${time}:00Z`);
110	  // Step 2: ask what Europe/Vilnius wall-clock that UTC instant displays.
111	  const fmt = new Intl.DateTimeFormat("en-GB", {
112	    timeZone: "Europe/Vilnius",
113	    year: "numeric", month: "2-digit", day: "2-digit",
114	    hour: "2-digit", minute: "2-digit", second: "2-digit",
115	    hour12: false,
116	  });
117	  const parts = fmt.formatToParts(new Date(naiveUtcMs));
118	  const get = (t: string) => parts.find(p => p.type === t)!.value;
119	  let hh = get("hour");
120	  if (hh === "24") hh = "00";
121	  const vilniusAsUtcMs = Date.UTC(
122	    Number(get("year")), Number(get("month")) - 1, Number(get("day")),
123	    Number(hh), Number(get("minute")), Number(get("second")),
124	  );
125	  // Offset = how many ms Vilnius is AHEAD of UTC at that instant (+2h or +3h).
126	  const offsetMs = vilniusAsUtcMs - naiveUtcMs;
127	  // Subtract offset to get the actual UTC instant for that Vilnius wall-clock time.
128	  return naiveUtcMs - offsetMs;
129	}
