135	// Returns the number of calendar days between today (Vilnius local) and the booking date.
136	function daysUntilBooking(dateStr: string): number {
137	  const fmt = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Vilnius" });
138	  const todayStr = fmt.format(new Date()); // YYYY-MM-DD
139	  const today = Date.parse(todayStr + "T00:00:00Z");
140	  const target = Date.parse(String(dateStr).slice(0, 10) + "T00:00:00Z");
141	  return Math.round((target - today) / (1000 * 60 * 60 * 24));
142	}
