144	function toMin(t: string): number {
145	  const [h, m] = t.split(":").map(Number);
146	  return h * 60 + m;
147	}
148	
149	function slotsBetween(startTime: string, endTime: string): string[] {
150	  const start = toMin(startTime);
151	  const end = toMin(endTime);
152	  const result: string[] = [];
153	  for (let m = start; m < end; m += 30) {
154	    const h = Math.floor(m / 60);
155	    const min = m % 60;
156	    result.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
157	  }
158	  return result;
159	}
